import{_ as l,l as i,o as e,c as n,v as r,p,x as t,d as o,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SparseGPT","description":"","frontmatter":{"title":"SparseGPT","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sparsegpt.md","filePath":"llm/sparsegpt.md","lastUpdated":1789023840000}'),m={name:"llm/sparsegpt.md"};function u(P,a,E,T,c,_){const s=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="sparsegpt" tabindex="-1">SparseGPT <a class="header-anchor" href="#sparsegpt" aria-label="Permalink to &quot;SparseGPT&quot;">​</a></h1><div class="epigraph"><p>把 GPTQ 的二阶补偿从「取整」改成「置零」：一层之内决定哪些权重留下，并把删掉的质量 squirt 到留下的值上。千亿参数可以剪完，而不必再训完。</p><footer>—— Frantar &amp; Alistarh, SparseGPT: Massive Language Models Can Be Accurately Pruned in One-Shot, ICML 2023</footer></div><p><a href="/llm/quant-eval-degradation">量化退化</a> 收束了 PTQ 基础。本课打开稀疏单元： <strong>SparseGPT</strong>。<a href="/llm/unstructured-sparsity">非结构化稀疏</a> 已写掩码与核的鸿沟；<a href="/llm/gptq">GPTQ</a> 已写 Hessian 补偿。缺口是一次性剪枝如何借用同一套 \\(\\min\\|\\hat W X-WX\\|\\)，约束从格子换成硬零。后课 Wanda 会丢掉二阶、只留幅度×激活；本课先把完整重建立住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>幅度剪枝假设 \\(|w|\\) 小则不重要。LLM 里小权重乘大激活可以很重要。OBQ 式剪枝每步挑最不疼的权重，规模不可行。SparseGPT 要：一次前向校准、逐层、能跑 175B、掩码非结构（或块结构）。问题与 GPTQ 平行，离散动作从 round 变成 prune。</p><p>没有稀疏核时，墙钟不变，只省存储（还要付索引）。本课主质量；<a href="/llm/two-four-sparsity">2:4</a> 再谈加速。不要用论文稀疏度乘量化 bit 当加速比，分工课已禁。</p><p><span class="marginnote">One-shot 指不必迭代重训到收敛，不是指零校准。校准 \\(X\\) 仍然关键，过拟合同样发生。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对一层，用校准 \\(X\\) 构 Hessian \\(\\sim XX^\\top\\)。按列（或块）选择保留集合（满足稀疏度或 N:M），置零的位置把残差经 Hessian 逆补偿到未处理权重——与 GPTQ 同一 squirt，动作是零而不是台阶。列序固定以保证复杂度。量化可以在同一框架后接（先剪再量化要重校准）。</p>',9)),(e(),p(h,null,{default:t(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%A0%A1%E5%87%86%20X%22%5D%20--%3E%20H%5B%22Hessian%22%5D%0A%20%20W%5B%22%E7%A8%A0%E5%AF%86%20W%22%5D%20--%3E%20SEL%5B%22%E6%8C%89%E5%88%97%E9%80%89%E4%BF%9D%E7%95%99%E4%BD%8D%22%5D%0A%20%20H%20--%3E%20SEL%0A%20%20SEL%20--%3E%20Z%5B%22%E7%BD%AE%E9%9B%B6%22%5D%0A%20%20Z%20--%3E%20CMP%5B%22%E8%A1%A5%E5%81%BF%E5%89%A9%E4%BD%99%E9%9D%9E%E9%9B%B6%22%5D%0A%20%20CMP%20--%3E%20M%5B%22%E7%A8%80%E7%96%8F%20W%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>实现上掩码非结构，部署若要 2:4，应在选择阶段就加 N:M 约束，而不是剪完再硬塞模式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次型与 GPTQ 相同：删掉的自由度变成等式约束（值为 0），牛顿步在剩余子空间减小重建误差。所以「剪完权重看起来变了」是功能：留下的值不是原值。只存掩码不存更新后的非零，会丢掉补偿，质量回到笨幅度剪。</p><p>校准域决定哪些方向被当成「能量」。换域后，为网页 PPL 保住的连接可能不是代码需要的。签字用分能力，同量化课。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要期望 50% 非结构在 GPU 上加速。不要把 SparseGPT 检查点当 QAT 稀疏的初始化而不看补偿后的值。不要与 Wanda 比而不锁校准与稀疏度。下一课 Wanda：更便宜的打分，无完整 squirt。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SparseGPT：一层重建 + Hessian 补偿的一次性剪枝，动作是置零。</li><li>留下的非零已被更新；只存掩码会丢补偿。</li><li>质量路径与 GPTQ 同源，核路径仍取决于结构约束。</li><li>校准过拟合与分能力验收同量化纪律。</li><li>出处：Frantar &amp; Alistarh, ICML 2023 SparseGPT。</li></ul>',8))])}const S=l(m,[["render",u]]);export{f as __pageData,S as default};
